package com.dbtraining.reconx.controller;
import com.dbtraining.reconx.dto.TradeEvent; import com.dbtraining.reconx.kafka.TradeEventProducer; import com.dbtraining.reconx.repository.DlqMessageRepository; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/v1/admin/dlq") @PreAuthorize("hasRole('ADMIN')") public class DlqAdminController { private final DlqMessageRepository repo; private final TradeEventProducer producer; private final ObjectMapper json; public DlqAdminController(DlqMessageRepository r,TradeEventProducer p,ObjectMapper j){repo=r;producer=p;json=j;} @GetMapping public Object list(){return repo.findAll();} @PostMapping("/replay") public Map<String,Object> replay(@RequestParam String eventId,@RequestParam(defaultValue="false") boolean dryRun)throws Exception{var msg=repo.findByEventId(eventId).orElseThrow(()->new IllegalArgumentException("No DLQ message: "+eventId));if(dryRun)return Map.of("dryRun",true,"wouldReplayTo",msg.getOriginalTopic(),"tradeRef",msg.getTradeRef());producer.publish(json.readValue(msg.getPayload(),TradeEvent.class));repo.delete(msg);return Map.of("replayed",true,"eventId",eventId);}}
